INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 39, 'theory', 'Quiz: testing');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 39, 0, 'Which property matters for a good test?', '["It depends on the result of a neighboring test", "It is small, fast, independent, and checks one idea", "It uses the real network", "It is longer than the code under test"]', 1, 'Independent, fast tests fail only when the code under test is broken.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 39, 1, 'What is the setUp method in TestCase for?', '["It runs the program", "It prepares a clean environment before each test", "It deletes tests", "It computes coverage"]', 1, 'setUp runs before every test_*, so tests don''t affect each other.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 39, 2, 'How do you check that a function raises ValueError on bad data?', '["assertEqual(f(), ValueError)", "with self.assertRaises(ValueError): f(...)", "try ... except: pass", "assert f() is None"]', 1, 'assertRaises reports a failure if no exception is raised.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 39, 3, 'What does unittest.mock.patch do?', '["Fixes bugs automatically", "Temporarily replaces an object (for example, a network function) with a mock for the duration of the test", "Speeds up tests", "Creates test data"]', 1, 'After the test, the replacement is undone; this is how code is isolated from the network, time, and randomness.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 39, 4, 'What does the cycle "red, green, refactor" mean?', '["Coloring the output", "First a failing test, then minimal code, then tidying up while the tests are green", "Three kinds of errors", "The order in which files are run"]', 1, 'This is the test-before-code approach (TDD): small steps, each confirmed by a test.');
